    PageHandlerInterface,
    PageHandlerPendingReceiver,
    PageHandlerRemote>(
    PageHandlerRemote,
    (receiver: PageHandlerPendingReceiver) => PageHandlerFactory.getRemote().createPageHandler(receiver));